    e15: "कुनै डेनिश व्यक्तिले तपाईंलाई केही बुझाइरहेको बेला कहिल्यै छिटोछिटो तीन पटक \"Ja-ja-ja!\" नभन्नुहोस् – यसको अर्थ \"अब रोक्नुहोस्, मलाई अरू सुन्न मन छैन!\" भनेर बुझिन्छ।",
