    e21: "\"Aha\" तर्क र तथ्यमा बढी केन्द्रित हुन्छ (\"अब मैले प्रणाली बुझेँ\"), जबकि \"Nåååh\" मा भावना र सहानुभूति पनि समेटिन्छ।",
